#!/usr/bin/env python3
import sys
import ssl
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"


def load_cert_text():
    with open(CERT_PATH) as f:
        return f.read()


def main():
    try:
        with open(CERT_PATH):
            pass
    except OSError as e:
        print(f"Certificate not found or unreadable: {e}")
        sys.exit(1)

    try:
        info = ssl._ssl._test_decode_cert(CERT_PATH)
    except Exception as e:
        print(f"Failed to load certificate: {e}")
        sys.exit(1)

    subject = dict(x[0] for x in info.get("subject", ()))
    common_name = subject.get("commonName", "<unknown>")

    not_after = info.get("notAfter")
    exp_date = None
    for fmt in ("%b %d %H:%M:%S %Y %Z", "%b %d %H:%M:%S %Y GMT"):
        try:
            exp_date = datetime.strptime(not_after, fmt)
            break
        except (ValueError, TypeError):
            continue

    print(f"Common Name: {common_name}")
    if exp_date is not None:
        print(f"Expiration Date: {exp_date.strftime('%Y-%m-%d')}")
    else:
        print(f"Expiration Date: {not_after}")

    print("Certificate verification successful")


if __name__ == "__main__":
    main()

